        'model'=>(string)($base['model']??''),'reasoning_effort'=>'medium','max_output_tokens'=>4200,
        'max_tool_calls_per_research_pass'=>2,'timeout_seconds'=>90,'max_provider_body_bytes'=>2097152,
        'minimum_unique_sources'=>4,'minimum_source_families'=>3,'minimum_counter_sources'=>1,
        'minimum_counter_families'=>1,'minimum_corroboration_sources'=>1,'minimum_corroboration_families'=>2,
        'authorization_ttl_seconds'=>900,'max_confirmed_map_characters'=>7000,
