}
function tw_deep_extract_text(array $r): string {$c=[];foreach(($r['output']??[]) as $i){if(!is_array($i)||($i['type']??'')!=='message')continue;foreach(($i['content']??[]) as $x){if(is_array($x)&&is_string($x['text']??null)&&trim($x['text'])!=='')$c[]=trim($x['text']);}}return trim(implode("\n\n",$c));}
function tw_deep_normalize_url(string $url): string {$url=trim($url);if($url===''||filter_var($url,FILTER_VALIDATE_URL)===false)return '';$p=parse_url($url);if(!is_array($p))return '';$s=strtolower((string)($p['scheme']??''));$h=strtolower((string)($p['host']??''));if(!in_array($s,['http','https'],true)||$h==='')return '';$path=(string)($p['path']??'/');$q=[];if(isset($p['query'])){parse_str((string)$p['query'],$q);foreach(array_keys($q) as $k)if(str_starts_with(strtolower((string)$k),'utm_')||in_array(strtolower((string)$k),['fbclid','gclid'],true))unset($q[$k]);}ksort($q);$n=$s.'://'.$h.($path!==''?$path:'/');if($q!==[])$n.='?'.http_build_query($q,'','&',PHP_QUERY_RFC3986);return $n;}
function tw_deep_source_family(string $url): string {$p=parse_url($url);if(!is_array($p))return '';$h=strtolower(rtrim((string)($p['host']??''),'.'));if($h==='')return '';foreach(['www.','m.','amp.'] as $pre)if(str_starts_with($h,$pre)){$h=substr($h,strlen($pre));break;}if(filter_var($h,FILTER_VALIDATE_IP)!==false)return $h;$l=array_values(array_filter(explode('.',$h),fn($x)=>$x!==''));$n=count($l);if($n<=2)return $h;$t=$l[$n-1];$s=$l[$n-2];if($n>=3&&in_array($s,['ac','co','com','edu','gov','net','org'],true)&&in_array($t,['au','br','jp','nz','uk','za'],true))return implode('.',array_slice($l,-3));return implode('.',array_slice($l,-2));}
function tw_deep_family_metrics(array $sources): array {$f=[];foreach($sources as $s){if(!is_array($s))continue;$x=(string)($s['family']??'');if($x==='')$x=tw_deep_source_family((string)($s['url']??''));if($x!=='')$f[$x]=true;}return ['family_count'=>count($f),'families'=>array_keys($f)];}
function tw_deep_usage_total(array $passes): array {$t=['input_tokens'=>0,'output_tokens'=>0,'reasoning_tokens'=>0];foreach($passes as $p){$u=is_array($p['usage']??null)?$p['usage']:[];foreach(array_keys($t) as $k)$t[$k]+=(int)($u[$k]??0);}$t['total_tokens']=$t['input_tokens']+$t['output_tokens'];return $t;}
function tw_deep_extract_sources(array $r): array {$s=[];foreach(($r['output']??[]) as $i){if(!is_array($i)||($i['type']??'')!=='web_search_call')continue;$a=$i['action']??null;if(!is_array($a))continue;foreach(($a['sources']??[]) as $x){if(!is_array($x))continue;$u=tw_deep_normalize_url((string)($x['url']??''));if($u==='')continue;$t=trim((string)($x['title']??'Source'));$s[$u]=['url'=>$u,'title'=>$t!==''?$t:'Source','family'=>tw_deep_source_family($u)];}}return array_values($s);}
function tw_deep_provider_pass(string $system,string $user,bool $withWeb): array {$cfg=tw_deep_config();$key=tw_openai_key();if($key==='')return ['ok'=>false,'message'=>'Research provider key unavailable.','quota_consumed'=>false];if($cfg['model']==='')return ['ok'=>false,'message'=>'Research model unavailable.','quota_consumed'=>false];$payload=['model'=>$cfg['model'],'store'=>false,'reasoning'=>['effort'=>$cfg['reasoning_effort']],'max_output_tokens'=>$cfg['max_output_tokens'],'input'=>[['role'=>'system','content'=>[['type'=>'input_text','text'=>$system]]],['role'=>'user','content'=>[['type'=>'input_text','text'=>$user]]]]];if($withWeb){$payload['tools']=[['type'=>'web_search']];$payload['tool_choice']='required';$payload['max_tool_calls']=$cfg['max_tool_calls_per_research_pass'];$payload['include']=['web_search_call.action.sources'];}$encoded=json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if(!is_string($encoded))return ['ok'=>false,'message'=>'Research request encoding failed.','quota_consumed'=>false];$raw='';$too=false;$ch=curl_init('https://api.openai.com/v1/responses');if($ch===false)return ['ok'=>false,'message'=>'Research provider initialization failed.','quota_consumed'=>false];$ok=curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>$encoded,CURLOPT_RETURNTRANSFER=>false,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>$cfg['timeout_seconds'],CURLOPT_WRITEFUNCTION=>static function($h,string $chunk)use(&$raw,&$too,$cfg):int{if(strlen($raw)+strlen($chunk)>$cfg['max_provider_body_bytes']){$too=true;return 0;}$raw.=$chunk;return strlen($chunk);}]);if(!$ok){curl_close($ch);return ['ok'=>false,'message'=>'Research provider request setup failed.','quota_consumed'=>false];}$ex=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$err=curl_error($ch);curl_close($ch);if($too)return ['ok'=>false,'message'=>'Research provider response exceeded safety limit.','quota_consumed'=>true];if($ex===false||$http<200||$http>=300)return ['ok'=>false,'message'=>'Research provider request failed.','diagnostic'=>$err!==''?$err:'http_'.$http,'quota_consumed'=>true];$d=json_decode($raw,true);if(!is_array($d))return ['ok'=>false,'message'=>'Research provider response was invalid.','quota_consumed'=>true];$text=tw_deep_extract_text($d);if($text==='')return ['ok'=>false,'message'=>'Research provider returned no usable analysis.','quota_consumed'=>true];$u=is_array($d['usage']??null)?$d['usage']:[];return ['ok'=>true,'text'=>$text,'sources'=>tw_deep_extract_sources($d),'response_id'=>is_string($d['id']??null)?$d['id']:'','usage'=>['input_tokens'=>(int)($u['input_tokens']??0),'output_tokens'=>(int)($u['output_tokens']??0),'reasoning_tokens'=>(int)($u['output_tokens_details']['reasoning_tokens']??0)],'quota_consumed'=>true];}

function tw_deep_base_system(): string {
    return "You are Trust-Worthy, a relentless evidence investigator. Follow evidence wherever it leads without protecting a political, religious, institutional, commercial, or media narrative. Treat official statements, fact-checks, news reports, viral posts, expert claims, and user assertions as claims to audit rather than authority to obey. Trace assertions toward original records and earliest accessible provenance. Search for evidence that would falsify your emerging hypothesis and report it prominently. Separate verified fact, allegation, inference, framing, missing context, contradiction, and unknowns. Never convert repetition into corroboration, domain diversity into independence, suspicion into evidence, or absence of evidence into proof of falsity. Never accuse an identifiable person of criminal conduct without evidence adequate to support that specific allegation. Do not stop merely because a respected source has issued a verdict: inspect its evidence and upstream sources. Your job is to discover what the evidence can actually establish, including uncomfortable results, while preserving provenance and uncertainty.";
}
function tw_deep_subject(string $q,string $c): string {return "CLAIM OR QUESTION:\n{$q}".($c!==''?"\n\nUSER CONTEXT:\n{$c}":'');}
function tw_deep_claim_map(string $q,string $c=''): array {[$v,$q,$c,$e]=tw_validate_trial_input($q,$c);if(!$v)return ['ok'=>false,'message'=>$e,'quota_consumed'=>false];return tw_deep_provider_pass(tw_deep_base_system(),tw_deep_subject($q,$c)."\n\nBefore web research, decompose this into independently testable assertions. Identify CENTRAL CLAIM; EXACT ATTRIBUTION CLAIMS; TESTABLE SUBCLAIMS; IMPLIED CLAIMS; KEY ENTITIES; IMPORTANT DATES; LOADED FRAMING; ALTERNATIVE HYPOTHESES; and MATERIAL QUESTIONS. For sensational or composite allegations, separate whether a person actually said something from whether the underlying proposition is independently true. Keep each item concise and editable. Do not research or issue a verdict.",false);}
function tw_deep_b64url_encode(string $b):string{return rtrim(strtr(base64_encode($b),'+/','-_'),'=');}
function tw_deep_b64url_decode(string $v):?string{if($v===''||preg_match('/^[A-Za-z0-9_-]+$/D',$v)!==1)return null;$p=(4-(strlen($v)%4))%4;$d=base64_decode(strtr($v.str_repeat('=',$p),'-_','+/'),true);return is_string($d)?$d:null;}
function tw_deep_authorization_path(string $n):string{return tw_private_dir().'/deep-auth-'.$n.'.json';}
function tw_deep_cleanup_authorizations():void{if(!tw_ai_prepare_private_dir())return;$m=glob(tw_private_dir().'/deep-auth-*.json');if(!is_array($m)||count($m)>10000)return;$cut=time()-3600;foreach($m as $p){if(!preg_match('/^deep-auth-[a-f0-9]{32}\.json$/D',basename($p)))continue;if(!tw_ai_private_path_exists($p)||!tw_ai_secure_existing_regular_file($p,0600))continue;$x=@filemtime($p);if(is_int($x)&&$x<$cut)@unlink($p);}}
function tw_deep_issue_authorization(string $ip,string $q,string $c,string $secret):string{if(!preg_match('/^[a-f0-9]{64}$/D',$ip)||$secret==='')return '';try{$n=bin2hex(random_bytes(16));}catch(Throwable $e){return '';}$cfg=tw_deep_config();$p=['v'=>1,'nonce'=>$n,'exp'=>time()+(int)$cfg['authorization_ttl_seconds'],'ip_hash'=>$ip,'question_hash'=>hash_hmac('sha256','deep-question|'.$q,$secret),'context_hash'=>hash_hmac('sha256','deep-context|'.$c,$secret)];$j=json_encode($p,JSON_UNESCAPED_SLASHES);if(!is_string($j))return '';$body=tw_deep_b64url_encode($j);$sig=hash_hmac('sha256','deep-auth|'.$body,$secret);$r=json_encode(['state'=>'issued','exp'=>$p['exp'],'payload_hash'=>hash('sha256',$body)],JSON_UNESCAPED_SLASHES);if(!is_string($r)||!tw_ai_atomic_private_write(tw_deep_authorization_path($n),$r."\n"))return '';tw_deep_cleanup_authorizations();return $body.'.'.$sig;}
function tw_deep_consume_authorization(string $token,string $ip,string $q,string $c,string $secret):bool{if($secret===''||strlen($token)>4096||!str_contains($token,'.'))return false;[$body,$sig]=explode('.',$token,2);if(!preg_match('/^[a-f0-9]{64}$/D',$sig)||!hash_equals(hash_hmac('sha256','deep-auth|'.$body,$secret),$sig))return false;$d=tw_deep_b64url_decode($body);if(!is_string($d))return false;$p=json_decode($d,true);if(!is_array($p)||(int)($p['v']??0)!==1)return false;$n=(string)($p['nonce']??'');if(!preg_match('/^[a-f0-9]{32}$/D',$n))return false;$exp=(int)($p['exp']??0);if($exp<time()||$exp>time()+1800||!hash_equals((string)($p['ip_hash']??''),$ip)||!hash_equals((string)($p['question_hash']??''),hash_hmac('sha256','deep-question|'.$q,$secret))||!hash_equals((string)($p['context_hash']??''),hash_hmac('sha256','deep-context|'.$c,$secret)))return false;try{return(bool)tw_ai_with_private_file_lock(tw_private_dir().'/deep-auth.lock',static function()use($n,$body,$exp):bool{$path=tw_deep_authorization_path($n);$raw=tw_ai_read_secure_regular_file($path,2,4096);if(!is_string($raw))return false;$r=json_decode(trim($raw),true);if(!is_array($r)||($r['state']??'')!=='issued'||(int)($r['exp']??0)!==$exp||$exp<time()||!hash_equals((string)($r['payload_hash']??''),hash('sha256',$body)))return false;$x=json_encode(['state'=>'consumed','exp'=>$exp,'payload_hash'=>hash('sha256',$body),'consumed_at'=>time()],JSON_UNESCAPED_SLASHES);return is_string($x)&&tw_ai_atomic_private_write($path,$x."\n");});}catch(Throwable $e){return false;}}
function tw_deep_receipt(string $stage,string $label,array $pass):array{$s=is_array($pass['sources']??null)?$pass['sources']:[];$f=tw_deep_family_metrics($s);return ['stage'=>$stage,'label'=>$label,'completed'=>(bool)($pass['ok']??false),'source_count'=>count($s),'source_family_count'=>(int)$f['family_count'],'sources'=>$s,'summary'=>is_string($pass['text']??null)?$pass['text']:'','at_utc'=>gmdate('c')];}

