[$valid,$question,$context,$error]=tw_validate_trial_input($question,$context);if(!$valid)return ['ok'=>false,'message'=>$error];$emit=static function(array $r)use($onReceipt):void{if($onReceipt!==null)$onReceipt($r);};$base=tw_deep_base_system();$subject=tw_deep_subject($question,$context);$cfg=tw_deep_config();$confirmedClaimMap=trim($confirmedClaimMap);if($confirmedClaimMap!==''){if(mb_strlen($confirmedClaimMap,'UTF-8')>(int)$cfg['max_confirmed_map_characters'])return ['ok'=>false,'message'=>'Confirmed claim map was too large.'];$decompose=['ok'=>true,'text'=>$confirmedClaimMap,'sources'=>[],'usage'=>[],'quota_consumed'=>false];$emit(tw_deep_receipt('decompose','Claim map confirmed',$decompose));}else{$decompose=tw_deep_claim_map($question,$context);if(!($decompose['ok']??false))return $decompose;$emit(tw_deep_receipt('decompose','Claim decomposed',$decompose));}
$passes=[];$plan=[
'origin'=>['Trace origin','Trace the exact wording and narrative backward. Seek earliest accessible appearance, archived versions, original language where relevant, and transformations between versions. Distinguish what was actually said or recorded from later paraphrase, splice, meme, headline, translation, or embellishment.'],
'primary'=>['Primary evidence','Seek primary records for every material subclaim: transcripts, video/audio, court records, statutes, filings, datasets, original studies, direct statements, archives, or equivalent. Do not substitute a fact-check or news article for an available primary record. State explicitly when primary evidence cannot be found.'],
'corroboration'=>['Independent corroboration','Seek genuinely separate evidence paths. Determine whether each apparent corroborator independently observed or obtained evidence. Discount outlets that merely repeat a wire report, press release, anonymous post, common dataset, or one another.'],
