'context'=>['Context and chronology','Construct the chronology and identify omitted context that changes meaning. Separate historical material recycled as current news. Distinguish association from coordination, rhetoric from operational evidence, allegation from adjudicated fact, and evidence about one actor from evidence about a broader institution or network.']];
foreach($plan as $stage=>[$label,$instruction]){$prior='';if($stage==='dependency'&&$passes!==[]){$chunks=[];foreach($passes as $ps=>$pp)$chunks[]=strtoupper((string)$ps)." PASS:\n".(string)($pp['text']??'');$prior="\n\nPRIOR PASS FINDINGS TO AUDIT FOR SHARED UPSTREAM DEPENDENCIES:\n".implode("\n\n",$chunks);}$pass=tw_deep_provider_pass($base,$subject."\n\nCONFIRMED CLAIM MAP:\n".$decompose['text'].$prior."\n\nPASS OBJECTIVE:\n{$instruction}\n\nDo not inherit a previous source's verdict. Report concise evidence, provenance, conflicts, and unresolved questions.",true);if(!($pass['ok']??false))return ['ok'=>false,'message'=>'Deep investigation stopped during '.strtolower($label).'.','stage'=>$stage,'detail'=>$pass['message']??'unknown'];$passes[$stage]=$pass;$emit(tw_deep_receipt($stage,$label,$pass));}
$unique=[];foreach($passes as $p)foreach(($p['sources']??[]) as $s){if(is_array($s)&&($u=(string)($s['url']??''))!=='')$unique[$u]=$s;}$all=tw_deep_family_metrics(array_values($unique));$counterSources=count($passes['counter']['sources']??[]);$cf=tw_deep_family_metrics($passes['counter']['sources']??[]);$corSources=count($passes['corroboration']['sources']??[]);$cof=tw_deep_family_metrics($passes['corroboration']['sources']??[]);$depSources=count($passes['dependency']['sources']??[]);$df=tw_deep_family_metrics($passes['dependency']['sources']??[]);$families=(int)$all['family_count'];$counterFamilies=(int)$cf['family_count'];$corFamilies=(int)$cof['family_count'];$depFamilies=(int)$df['family_count'];$floor=count($unique)>=$cfg['minimum_unique_sources']&&$families>=$cfg['minimum_source_families']&&$counterSources>=$cfg['minimum_counter_sources']&&$counterFamilies>=$cfg['minimum_counter_families']&&$corSources>=$cfg['minimum_corroboration_sources']&&$corFamilies>=$cfg['minimum_corroboration_families'];$packet=[];foreach($passes as $stage=>$p)$packet[]=strtoupper($stage)." PASS:\n".$p['text'];$note="SOURCE-DIVERSITY RECEIPT:\nUnique URLs: ".count($unique)."\nDistinct domain families: {$families}\nCounterevidence domain families: {$counterFamilies}\nCorroboration domain families: {$corFamilies}\nDependency-audit domain families: {$depFamilies}\nA domain-family count is only a conservative diversity heuristic. Different domains can still repeat the same wire story, press release, filing, study, witness, or originating claim. Use the SOURCE DEPENDENCY AND ECHO TRACING pass to discount shared upstream chains; never describe domain-family counts as proof of editorial independence.";$instruction=$floor?"The evidence floor is met. Produce a final synthesis. Begin with exactly two machine-readable lines: VERDICT: one of SUPPORTED, LIKELY, MIXED, UNLIKELY, CONTRADICTED; PROBABILITY: integer 0-100. Probability is evidence-conditioned confidence, not objective truth. Evaluate EACH MATERIAL SUBCLAIM separately before the central claim. Explain verified facts, unsupported allegations, inference, missing context, strongest evidence, strongest counterevidence, provenance/echo chains, independent evidence paths, alternative hypotheses, unresolved unknowns, and what evidence would change the conclusion. Do not let the reputation of a source substitute for its evidence." : "The evidence floor is NOT met. Do not issue a probability. Begin exactly: VERDICT: INSUFFICIENT EVIDENCE — NO VERDICT and PROBABILITY: NONE. Explain searches, evidence, gaps, dependency/echo risks, failed diversity gates, competing hypotheses, and what evidence would be required.";$syn=tw_deep_provider_pass($base,$subject."\n\nCONFIRMED CLAIM MAP:\n".$decompose['text']."\n\nEVIDENCE PACKET:\n".implode("\n\n",$packet)."\n\n".$note."\n\n".$instruction,false);if(!($syn['ok']??false))return $syn;$verdict='INSUFFICIENT EVIDENCE — NO VERDICT';if(preg_match('/^VERDICT:\s*(.+)$/mi',$syn['text'],$m))$verdict=trim($m[1]);$prob=null;if($floor&&preg_match('/^PROBABILITY:\s*(\d{1,3})\s*$/mi',$syn['text'],$m)){ $x=(int)$m[1];if($x>=0&&$x<=100)$prob=$x;}if(!$floor){$verdict='INSUFFICIENT EVIDENCE — NO VERDICT';$prob=null;}$usage=tw_deep_usage_total(array_merge([$decompose],array_values($passes),[$syn]));$final=['stage'=>'synthesis','label'=>'Finding generated','completed'=>true,'source_count'=>count($unique),'source_family_count'=>$families,'counter_family_count'=>$counterFamilies,'corroboration_family_count'=>$corFamilies,'dependency_family_count'=>$depFamilies,'evidence_floor_met'=>$floor,'verdict'=>$verdict,'probability'=>$prob,'usage'=>$usage,'at_utc'=>gmdate('c')];$emit($final);try{$id='TW-'.gmdate('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));}catch(Throwable $e){$id='TW-'.gmdate('Ymd-His');}$receipts=[tw_deep_receipt('decompose',$confirmedClaimMap!==''?'Claim map confirmed':'Claim decomposed',$decompose)];foreach($passes as $stage=>$p)$receipts[]=tw_deep_receipt($stage,$plan[$stage][0],$p);$receipts[]=$final;return ['ok'=>true,'investigation_id'=>$id,'claim'=>$question,'claim_map'=>$decompose['text'],'receipts'=>$receipts,'sources'=>array_values($unique),'metrics'=>['unique_sources'=>count($unique),'source_families'=>$families,'counter_sources'=>$counterSources,'counter_families'=>$counterFamilies,'corroboration_sources'=>$corSources,'corroboration_families'=>$corFamilies,'dependency_sources'=>$depSources,'dependency_families'=>$depFamilies,'source_independence_status'=>'dependency_audit_plus_domain_family_heuristic','evidence_floor_met'=>$floor,'usage'=>$usage],'verdict'=>$verdict,'probability'=>$prob,'analysis'=>$syn['text']];}
